import{_ as e,o as l,c as o,ag as r}from"./chunks/framework.C5oN-8Wt.js";const m=JSON.parse('{"title":"v0.4.0-alpha 模块教学文档","description":"","frontmatter":{},"headers":[],"relativePath":"v0.4.0-alpha/index.md","filePath":"v0.4.0-alpha/index.md"}'),t={name:"v0.4.0-alpha/index.md"};function i(d,a,s,h,n,c){return l(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="v0-4-0-alpha-模块教学文档" tabindex="-1">v0.4.0-alpha 模块教学文档 <a class="header-anchor" href="#v0-4-0-alpha-模块教学文档" aria-label="Permalink to &quot;v0.4.0-alpha 模块教学文档&quot;">​</a></h1><p>已发布版本。适用 GNU Radio 3.10.12.0。</p><h2 id="获取软件" tabindex="-1">获取软件 <a class="header-anchor" href="#获取软件" aria-label="Permalink to &quot;获取软件&quot;">​</a></h2><p><strong>v0.4.0-alpha 已发布，为 Alpha 测试版。</strong> 安装包通过产品交付渠道提供，本教学站公开提供模块文档和实验工程。对应版本源码与构建说明向软件接收者提供。</p><p>本版将全部模块集中到统一模块库；通信、导航与监视入口提供对应的内置实验和实验说明。从左侧目录选择模块，先看接线和观察方法，再按参数表调整实验。文章按模块类型编写，同一类型的多个实例共用。</p><h2 id="从程序开始第一个实验" tabindex="-1">从程序开始第一个实验 <a class="header-anchor" href="#从程序开始第一个实验" aria-label="Permalink to &quot;从程序开始第一个实验&quot;">​</a></h2><p>在“帮助 → 快速入门”选择“开始操作引导”，跟随提示完成幅度、频率与相位实验。十二个内置示例打开后都是独立工作副本，可另存为自己的工程；示例旁的“实验说明”和“帮助 → 入门教程”始终可以打开对应网页。</p><p>观察器的时域曲线支持 A／B 测量：选择真实样本读出时间和数值，比较周期、峰谷或滤波前后。进入测量会定格当前波形，后台实验继续运行。</p><h2 id="没有通信基础-从这里开始" tabindex="-1">没有通信基础，从这里开始 <a class="header-anchor" href="#没有通信基础-从这里开始" aria-label="Permalink to &quot;没有通信基础，从这里开始&quot;">​</a></h2><p><a href="./learn/">低空通信、导航与监视学习路径</a>从无人机状态回传切入，依次认识幅度、频率、相位、采样、时域／频谱／瀑布、噪声滤波、I/Q 与基础调制判决。每课只研究少量概念，提供独立工程、操作步骤和单参数对照；原有综合工程继续保留在模块文章中。</p><h2 id="先做一次实验" tabindex="-1">先做一次实验 <a class="header-anchor" href="#先做一次实验" aria-label="Permalink to &quot;先做一次实验&quot;">​</a></h2><ol><li>从模块文章下载 <code>.cnsproj</code>，在 Master 的“文件 → 打开工程”载入。</li><li>从“编辑 → 插入”打开观察器，在参数页选择文章指定的输出。</li><li>需要调整频谱时，打开“运行 → 频谱设置…”，选择 FFT 长度、窗函数和重叠比例，点击“应用”。</li><li>按 <strong>F5</strong> 运行；<strong>Ctrl+F5</strong> 只准备，<strong>Shift+F5</strong> 停止当前本地任务。</li><li>保存工程会保留图、参数与已有运行快照；重新打开不会恢复样本或运行进程。</li></ol><p>本站示例均为 <strong>PC 本地仿真</strong>。阅读网站需要网络，本地实验无需登录或联网。</p><h2 id="从调频与判决开始" tabindex="-1">从调频与判决开始 <a class="header-anchor" href="#从调频与判决开始" aria-label="Permalink to &quot;从调频与判决开始&quot;">​</a></h2><p>新增的<a href="./modules/frequency_modulator/">调频</a>、<a href="./modules/magphase_split/">幅相分解</a>、<a href="./modules/quadrature_demod/">正交解调</a>和<a href="./modules/binary_slicer/">二值判决</a>可以串成一个小实验。进入这些文章可下载调频与判决示例 <code>modulation-chain.cnsproj</code>，并查看各模块的具体接线与观察步骤。</p><p>示例以 4096 Hz 采样率送入常量 1，调频灵敏度为 π/8，预期产生模长约为 1、频率约 +256 Hz 的复数信号。先选择调频输出观察复数频谱，再分别选择幅相分解的两路输出，比较恒定包络与绕回的主值相位。</p><p>正交解调倍率取 8/π 时，预期首项为 0，后续解调值约为 1。二值判决把零和正值均判为索引 1，再经 BPSK 映射得到复数点 <code>+1+j0</code>。这条链便于区分模拟幅度、相位 rad、解调值和码元索引：它们的数据含义不同，不能仅因为显示为数字就互换使用。</p><h2 id="如何读参数表" tabindex="-1">如何读参数表 <a class="header-anchor" href="#如何读参数表" aria-label="Permalink to &quot;如何读参数表&quot;">​</a></h2><p>表中默认值是内置默认，不会覆盖你的本机设置或已有工程。“可在线应用”须显式应用并查看节点回执；其余字段先停止、重新准备。同组参数、端口类型和实际采样率须满足文章说明的关联约束。</p><p><code>numeric_f64</code> / <code>complex_f64</code> 是 Master 通道标识；当前 GNU 原生浮点流分别为 float32 / complex64。整数和 byte 保留原生宽度。向量的一个 item 含 vlen 个分量，采样率和样本数按 item 计算；数值工具须显式选择分量。</p><h2 id="设置整个工程的频谱" tabindex="-1">设置整个工程的频谱 <a class="header-anchor" href="#设置整个工程的频谱" aria-label="Permalink to &quot;设置整个工程的频谱&quot;">​</a></h2><p>打开工程后，从“运行 → 频谱设置…”进入“频谱分析参数”对话框。频谱配置属于当前工程，统一作用于本次任务全部非码元输出；同一路输出的观察器共用这份实际频谱。码元索引不生成模拟幅度频谱。</p><table tabindex="0"><thead><tr><th>选项</th><th>可选值</th><th>怎样理解</th></tr></thead><tbody><tr><td>FFT 长度 N</td><td>256、512、1024、2048、4096、8192</td><td>每个窗口使用 N 个连续 item；频点间隔为实际输出采样率 Fs 除以 N。</td></tr><tr><td>窗函数</td><td>矩形、周期 Hann、周期 Hamming、周期 Blackman–Harris</td><td>决定窗口内样本的加权方式，影响谱峰宽度与泄漏；后三种均采用周期形式。</td></tr><tr><td>重叠比例</td><td>0%、50%、75%</td><td>相邻窗口共用的样本比例；比例越高，帧间隔越短，实际采样率保持不变。</td></tr></tbody></table><p>内置默认配置如下；未带频谱设置的旧格式工程采用相同的固定兼容值。</p><table tabindex="0"><thead><tr><th>字段</th><th>内置默认值</th></tr></thead><tbody><tr><td><code>fft_length</code></td><td><code>1024</code></td></tr><tr><td><code>overlap_percent</code></td><td><code>0</code></td></tr><tr><td><code>window</code></td><td><code>hann_periodic</code></td></tr><tr><td>派生步长 <code>hop_length</code></td><td><code>1024</code> item</td></tr></tbody></table><p>点击“应用”会将选项写入工程草稿，<strong>下次准备时生效</strong>。运行中的任务继续使用已经准备的实际配置；要采用新配置，先停止，再重新准备和运行。新准备会重新累计频谱窗口。</p><p>工程保存草稿配置，并在实际运行快照中分别保留当次实际配置；后续编辑不会改写旧运行的含义。旧历史没有记录的频谱配置保持未记录，不用新默认补成已知实值。重新打开工程恢复配置与已有快照，开始新的运行后才会产生新的样本和频谱。</p><h2 id="频率与幅值怎么读" tabindex="-1">频率与幅值怎么读 <a class="header-anchor" href="#频率与幅值怎么读" aria-label="Permalink to &quot;频率与幅值怎么读&quot;">​</a></h2><p>每个输出使用自己的实际采样率 Fs，抽取、插值、映射或信道速率变化后的输出应按各自 Fs 读谱。相同 N 不代表不同输出具有相同的 Hz 刻度。向量按分量分别变换：每个分量都使用连续 N 个 item，vlen 不会把窗口的时间长度乘大。</p><p>实数频谱从 DC 到奈奎斯特，共 N/2+1 个频点；复数频谱为移频双边谱，共 N 个频点，从 −Fs/2 起。两者的频点间隔都是 <strong>Fs/N</strong>。幅值按窗系数之和归一化，实数仅对非 DC、非奈奎斯特频点倍增；复数不套用这项单边系数。</p><p>纵轴表示<strong>线性峰值幅度</strong>，不是功率或功率谱密度（PSD）。选择 FFT 长度、窗和重叠只改变频谱分析方式，时域样本与实际采样率保持原值。比较不同设置时，先核对频率刻度、窗口长度和幅值定义。</p><h2 id="窗口时长与帧间隔" tabindex="-1">窗口时长与帧间隔 <a class="header-anchor" href="#窗口时长与帧间隔" aria-label="Permalink to &quot;窗口时长与帧间隔&quot;">​</a></h2><p>设步长为 H，<code>H = N × (100 − overlap_percent) / 100</code>。窗口时长是 <strong>N/Fs</strong>，相邻帧的间隔是 <strong>H/Fs</strong>；有重叠时，这两个时间不同。第 j 帧（j 从 0 开始）覆盖 item 区间 <code>[jH, jH+N)</code>，起始时间为 <code>jH/Fs</code>。</p><p>一路输出已经发布 S 个 item 时，预期完整窗口数为：S 小于 N 时是 0；否则是 <code>1 + floor((S − N) / H)</code>。各输出按自己的样本数、Fs 和窗口累计，不能拿一路的帧数代替另一路。这是由完整窗口推导的数量，不是历史中额外保存的实际接收计数。</p><p>不足一个完整窗口的尾段不补零、不生成频谱；尾段仍属于时域输出。缩短传输批次或刷新观察器不会把这些尾样本变成完整窗口。</p><h2 id="与滤波器的设计窗区分" tabindex="-1">与滤波器的设计窗区分 <a class="header-anchor" href="#与滤波器的设计窗区分" aria-label="Permalink to &quot;与滤波器的设计窗区分&quot;">​</a></h2><p>这里的窗用于<strong>观察频谱</strong>。低通、高通、带通模块中的 <code>window</code> 和 <code>window_param</code> 用于设计滤波抽头，决定模块实际怎样处理信号；它们的选项和参数含义见各模块文章。调整工程的频谱窗会改变观察方式，调整滤波器的设计窗则会改变滤波结果，两处设置分别保存、分别应用。</p><h2 id="从距离与延迟认识导航和监视" tabindex="-1">从距离与延迟认识导航和监视 <a class="header-anchor" href="#从距离与延迟认识导航和监视" aria-label="Permalink to &quot;从距离与延迟认识导航和监视&quot;">​</a></h2><ul><li><a href="./learn/01-position-from-ranges/">三段距离求位置</a>：坐标发生器 → 测距模拟器 → 二维定位解算器。</li><li><a href="./learn/02-find-delay/">相关找延迟</a>：同一序列分为参考与延时分支，由相关器观察正负 lag。</li><li><a href="./learn/03-delay-to-distance/">延迟换距离</a>：相关器 → 峰值检测器 → 测距器，分清样本数、秒数与米数。</li></ul><p>这三组实验共享同一张流程图和观察器。坐标与测距是局部平面软件模型；相关使用完整有限窗口，不代表真实 GNSS、雷达或设备采集。</p><h2 id="多工程与慢速观察" tabindex="-1">多工程与慢速观察 <a class="header-anchor" href="#多工程与慢速观察" aria-label="Permalink to &quot;多工程与慢速观察&quot;">​</a></h2><p>左侧“文件”列出已经打开的工程，点击即可切换。通信、导航和监视栏提供各自模块，均可拖入同一工程。任意时刻只运行一个实验：切换工程不停止当前运行，运行另一个工程会先结束前一个任务。</p><p>PC 软件仿真可在准备前选择 <strong>0.1×、0.25×、0.5×、1×</strong>，新工程默认 1×，运行中保持所选倍率。慢速改变计算推进的墙钟节奏，样本时间、采样率与频率含义保持原值。</p><h2 id="源码许可" tabindex="-1">源码许可 <a class="header-anchor" href="#源码许可" aria-label="Permalink to &quot;源码许可&quot;">​</a></h2><p>CNS Master 自有软件源码采用 GNU GPLv3（GPL-3.0-only）；第三方组件保留各自许可。对应版本源码与构建说明向软件接收者提供。</p><h2 id="模块目录" tabindex="-1">模块目录 <a class="header-anchor" href="#模块目录" aria-label="Permalink to &quot;模块目录&quot;">​</a></h2><ul><li><a href="./modules/signal_source/">信号源</a></li><li><a href="./modules/noise_source/">噪声源</a></li><li><a href="./modules/add/">加法器</a></li><li><a href="./modules/low_pass/">低通滤波器</a></li><li><a href="./modules/multiply/">乘法器</a></li><li><a href="./modules/gain/">增益器</a></li><li><a href="./modules/delay/">延时器</a></li><li><a href="./modules/high_pass/">高通滤波器</a></li><li><a href="./modules/band_pass/">带通滤波器</a></li><li><a href="./modules/fir/">FIR 滤波器</a></li><li><a href="./modules/complex_signal_source/">复数信号源</a></li><li><a href="./modules/complex_noise_source/">复数噪声源</a></li><li><a href="./modules/complex_add/">复数加法器</a></li><li><a href="./modules/complex_low_pass/">复数低通滤波器</a></li><li><a href="./modules/complex_multiply/">复数乘法器</a></li><li><a href="./modules/complex_gain/">复数增益器</a></li><li><a href="./modules/complex_delay/">复数延时器</a></li><li><a href="./modules/complex_high_pass/">复数高通滤波器</a></li><li><a href="./modules/complex_band_pass/">复数带通滤波器</a></li><li><a href="./modules/complex_fir/">复数FIR 滤波器</a></li><li><a href="./modules/iq_combine/">I/Q 合成器</a></li><li><a href="./modules/iq_split/">I/Q 分解器</a></li><li><a href="./modules/random_symbols/">随机码元发生器</a></li><li><a href="./modules/symbol_mapper/">符号映射器</a></li><li><a href="./modules/symbol_slicer/">符号判决器</a></li><li><a href="./modules/channel_model/">信道模拟器</a></li><li><a href="./modules/vector_source/">向量点表源</a></li><li><a href="./modules/magphase_split/">幅相分解</a></li><li><a href="./modules/frequency_modulator/">调频</a></li><li><a href="./modules/quadrature_demod/">正交解调</a></li><li><a href="./modules/binary_slicer/">二值判决</a></li><li><a href="./modules/coordinate_source/">坐标发生器</a></li><li><a href="./modules/range_simulator/">测距模拟器</a></li><li><a href="./modules/position_solver_2d/">二维定位解算器</a></li><li><a href="./modules/correlator/">相关器</a></li><li><a href="./modules/peak_detector/">峰值检测器</a></li><li><a href="./modules/range_estimator/">测距器</a></li></ul>',47)])])}const u=e(t,[["render",i]]);export{m as __pageData,u as default};
